// This stage intentionally does not approve, reject, or contact a seller.
// It prepares an auditable review payload for Notion, Airtable, Slack, or a human queue.
const deal = $input.item.json;
const highRisks = (deal.riskRegister || []).filter(r => r.severity === 'high');
const nextStatus = highRisks.length ? 'Escalated Review' : 'Under Review';
const reviewChecklist = [
  'Verify property-specific comparable sales and ARV',
  'Verify rehab scope with contractor estimates',
  'Verify taxes, insurance, HOA, and financing assumptions',
  'Confirm strategy-specific metrics and downside scenario',
  'Record a human approval or rejection with rationale',
];
return { json: { ...deal, reviewStatus: nextStatus, humanReviewRequired: true, reviewChecklist, reviewSummary: { recommendation: deal.recommendation, highRiskCount: highRisks.length, riskCodes: (deal.riskRegister || []).map(r => r.code), scenarioSummary: (deal.scenarios || []).map(s => ({ name: s.name, netEquitySpread: s.netEquitySpread, capRate: s.capRate, dscr: s.dscr })) }, auditTrail: [...(deal.auditTrail || []), { stage: 'human_review_gate', at: new Date().toISOString(), status: nextStatus, automatedDecision: 'none' }] } };
